{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C28"],
      "claim": "Halofantrine, the closest structural analogue sharing the dibutylamino-hydroxy side chain and halogenated aromatic core, is reported to have low and erratic oral bioavailability in humans and animals, supporting a low F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C27"],
      "claim": "In malaria patients, halofantrine oral doses eight-fold higher than intravenous doses produced similar peak plasma concentrations, implying an oral F well below 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C30"],
      "claim": "Zotepine, a chlorinated tricyclic with a basic side chain, has an absolute oral bioavailability of only 7-13%, providing additional support for low F in this lipophilic tricyclic amine class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "A retrospective halofantrine analysis estimated average F of approximately 30% in fasted humans, which is above the 20% threshold and represents the main contradictory evidence.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Predicted low: the closest analogue halofantrine is repeatedly characterized as having low/erratic oral bioavailability, and a dose-ratio comparison suggests F <20%. The query's even more lipophilic, poorly soluble scaffold is expected to be absorption-limited. The single 30% halofantrine estimate is an average with wide variability and does not outweigh the low-bioavailability pattern.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for lumefantrine in humans.",
    "Halofantrine quantitative F is mixed: ~30% average versus <20% implied by dose comparisons, creating threshold uncertainty.",
    "No intravenous formulation for lumefantrine is available, so true absolute F is not directly established."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

